// Days 183-274 — Part 3
import type { Day } from '../lib/types';

const vid = (k: string, posterKey?: string) => ({ src: k, poster: posterKey });

const day = (d: Omit<Day, 'id' | 'date' | 'isoDate' | 'composition'> & { id: number }): Day => {
  const monthStarts = [0, 31, 59, 90, 120, 151, 181, 212, 243, 273, 304, 334];
  const monthNames = ['JAN','FEB','MAR','APR','MAY','JUN','JUL','AUG','SEP','OCT','NOV','DEC'];
  let m = 0;
  for (let i = 0; i < monthStarts.length; i++) {
    if (d.id > monthStarts[i]) { m = i; }
  }
  const dayOfMonth = d.id - monthStarts[m];
  const date = `${monthNames[m]} ${String(dayOfMonth).padStart(2, '0')}`;
  const iso = `2026-${String(m+1).padStart(2,'0')}-${String(dayOfMonth).padStart(2,'0')}`;
  const rotations: Day['composition'][] = [
    'full-bleed-video', 'vertical-video-side', 'panoramic-image', 'split-screen',
    'image-typography', 'text-floating-video', 'photo-collage', 'asymmetric',
    'centered-image-negative', 'double-page', 'typography-dominant',
    'video-photo-sequence', 'vertical-title', 'photo-essay', 'typographic-essay',
  ];
  return { ...d, date, isoDate: iso, composition: rotations[d.id % rotations.length] } as Day;
};

